CREATE TABLE forms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), title text NOT NULL, slug text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','closed','archived')), version integer NOT NULL DEFAULT 1, definition jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,id), UNIQUE(company_id,slug));
-- A response row exists from the respondent's first answer; it stays 'partial' until the form is submitted.
CREATE TABLE form_responses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL, form_id uuid NOT NULL, session_key uuid NOT NULL, status text NOT NULL DEFAULT 'partial' CHECK(status IN ('partial','completed')), form_version integer NOT NULL, answers jsonb NOT NULL DEFAULT '{}', position text NOT NULL DEFAULT '', ending_id text, started_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, FOREIGN KEY(company_id,form_id) REFERENCES forms(company_id,id), UNIQUE(form_id,session_key), CHECK((status='completed') = (completed_at IS NOT NULL)));
CREATE INDEX form_responses_form ON form_responses(form_id,started_at DESC);
